void rtc_init   ( Rtc_Func rtc_func )
{    
	PCONP |= (1u << 9) ;

	isr_set_vector( ISR_ID_RTC , ISR_PRI_10 ,  ISR_TYPE_IRQ_FAST , rtc_func );

	wake_register( (Wake_Func)rtc_wake );

	RTC_CCR   = 0x02 ; /* CTC reset */
#ifdef DEV_LPC_236x	
	RTC_CISS  = 0x87 ; /* Subsecond Interrupt enable , one interrupt at 62.5 ms */	
	RTC_CIIR  = 0    ; /* Counter Increment Interrupt disable                   */		
#else
	RTC_CIIR  = 0x1    ; /* Second Counter Increment Interrupt enable           */		
#endif
	RTC_CCR   = 0x11 ; /* Clock enable , use external 32KHz crystal             */
		
#ifdef DEV_LPC_236x
    INTWAKE |= (1u << 15);
#endif
}

